import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';
import { employeeApi, departmentApi, branchApi, designationApi } from '../../api/services';
import { Button, Input, Select, Modal, Table, Badge, Pagination } from '../../components/ui';
import { Plus, Search, Pencil, Trash2, Upload } from 'lucide-react';
import toast from 'react-hot-toast';

const statusColor = { ACTIVE: 'green', PROBATION: 'yellow', RESIGNED: 'red', TERMINATED: 'red', ON_LEAVE: 'blue' };

export default function EmployeesPage() {
  const qc = useQueryClient();
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState('');
  const [deptFilter, setDeptFilter] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);

  const { data, isLoading } = useQuery({
    queryKey: ['employees', page, search, deptFilter],
    queryFn: () => employeeApi.search({ q: search || undefined, departmentId: deptFilter || undefined, page, size: 20 }),
  });

  const { data: depts } = useQuery({ queryKey: ['departments-all'], queryFn: () => departmentApi.getAll() });
  const { data: branches } = useQuery({ queryKey: ['branches-all'], queryFn: () => branchApi.getAll() });
  const { data: designations } = useQuery({ queryKey: ['designations-all'], queryFn: () => designationApi.getAll() });

  const employees = data?.data?.data?.content || [];
  const totalPages = data?.data?.data?.totalPages || 0;

  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm();

  const createMutation = useMutation({
    mutationFn: employeeApi.create,
    onSuccess: () => { qc.invalidateQueries(['employees']); toast.success('Employee created'); closeModal(); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed to create'),
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => employeeApi.update(id, data),
    onSuccess: () => { qc.invalidateQueries(['employees']); toast.success('Employee updated'); closeModal(); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed to update'),
  });

  const deleteMutation = useMutation({
    mutationFn: employeeApi.delete,
    onSuccess: () => { qc.invalidateQueries(['employees']); toast.success('Employee deleted'); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed to delete'),
  });

  const openCreate = () => { setEditing(null); reset({}); setModalOpen(true); };
  const openEdit = (emp) => { setEditing(emp); reset(emp); setModalOpen(true); };
  const closeModal = () => { setModalOpen(false); setEditing(null); reset({}); };

  const onSubmit = (formData) => {
    if (editing) updateMutation.mutate({ id: editing.id, data: formData });
    else createMutation.mutate(formData);
  };

  const columns = [
    { key: 'employeeCode', label: 'Code' },
    { key: 'name', label: 'Name', render: (r) => `${r.firstName} ${r.lastName}` },
    { key: 'email', label: 'Email' },
    { key: 'mobile', label: 'Mobile' },
    { key: 'employmentStatus', label: 'Status', render: (r) => <Badge label={r.employmentStatus} color={statusColor[r.employmentStatus] || 'gray'} /> },
    { key: 'employmentType', label: 'Type', render: (r) => <Badge label={r.employmentType} color="indigo" /> },
    {
      key: 'actions', label: 'Actions', render: (r) => (
        <div className="flex gap-2">
          <button onClick={() => openEdit(r)} className="p-1.5 rounded hover:bg-slate-100 text-slate-500"><Pencil size={14} /></button>
          <button onClick={() => { if (window.confirm('Delete this employee?')) deleteMutation.mutate(r.id); }} className="p-1.5 rounded hover:bg-red-50 text-red-400"><Trash2 size={14} /></button>
        </div>
      )
    },
  ];

  const deptList = depts?.data?.data?.content || depts?.data?.data || [];
  const branchList = branches?.data?.data?.content || branches?.data?.data || [];
  const desgList = designations?.data?.data?.content || designations?.data?.data || [];

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex flex-wrap gap-3 items-center justify-between">
        <div className="flex gap-2 flex-wrap">
          <div className="relative">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              className="pl-9 pr-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 w-56"
              placeholder="Search employees..."
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(0); }}
            />
          </div>
          <select
            className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white"
            value={deptFilter}
            onChange={(e) => { setDeptFilter(e.target.value); setPage(0); }}
          >
            <option value="">All Departments</option>
            {deptList.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
        <Button onClick={openCreate}><Plus size={16} /> Add Employee</Button>
      </div>

      <Table columns={columns} data={employees} loading={isLoading} />
      <Pagination page={page} totalPages={totalPages} onPageChange={setPage} />

      {/* Create / Edit Modal */}
      <Modal open={modalOpen} onClose={closeModal} title={editing ? 'Edit Employee' : 'Add Employee'} size="lg">
        <form onSubmit={handleSubmit(onSubmit)} className="grid grid-cols-2 gap-4">
          <Input label="First Name" error={errors.firstName?.message} {...register('firstName', { required: 'Required' })} />
          <Input label="Last Name" error={errors.lastName?.message} {...register('lastName', { required: 'Required' })} />
          <Input label="Email" type="email" error={errors.email?.message} {...register('email', { required: 'Required' })} />
          <Input label="Mobile" {...register('mobile')} />
          <Select label="Gender" {...register('gender')}>
            <option value="">Select</option>
            <option value="MALE">Male</option>
            <option value="FEMALE">Female</option>
            <option value="OTHER">Other</option>
          </Select>
          <Input label="Date of Birth" type="date" {...register('dateOfBirth')} />
          <Input label="Joining Date" type="date" error={errors.joiningDate?.message} {...register('joiningDate', { required: 'Required' })} />
          <Input label="Nationality" {...register('nationality')} />
          <Select label="Department" error={errors.departmentId?.message} {...register('departmentId', { required: 'Required' })}>
            <option value="">Select Department</option>
            {deptList.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </Select>
          <Select label="Designation" error={errors.designationId?.message} {...register('designationId', { required: 'Required' })}>
            <option value="">Select Designation</option>
            {desgList.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </Select>
          <Select label="Branch" {...register('branchId')}>
            <option value="">Select Branch</option>
            {branchList.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
          </Select>
          <Select label="Employment Type" {...register('employmentType')}>
            <option value="">Select</option>
            <option value="FULL_TIME">Full Time</option>
            <option value="PART_TIME">Part Time</option>
            <option value="CONTRACT">Contract</option>
            <option value="INTERN">Intern</option>
          </Select>
          <Select label="Marital Status" {...register('maritalStatus')}>
            <option value="">Select</option>
            <option value="SINGLE">Single</option>
            <option value="MARRIED">Married</option>
            <option value="DIVORCED">Divorced</option>
          </Select>
          <Input label="Work Location" {...register('workLocation')} />
          <div className="col-span-2">
            <Input label="Current Address" {...register('currentAddress')} />
          </div>
          <div className="col-span-2 flex justify-end gap-3 pt-2">
            <Button type="button" variant="secondary" onClick={closeModal}>Cancel</Button>
            <Button type="submit" disabled={isSubmitting}>
              {editing ? 'Update' : 'Create'}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
